// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    PRIVATE_ETH_CELL c;
    LogAddr logAddr;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
        logAddr = new LogAddr();
    }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(logAddr));
        vm.assume(uint256(uint160(actor)) > 10);
        amount = bound(amount, 0, address(this).balance + 1 ether);

        vm.prank(address(this));
        c.SetLogFile(address(logAddr));

        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.Deposit{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }
        // A deposit to a contract that was properly set as the LogFile must always succeed.
        assertTrue(ok);
    }
}

contract LogAddr {
    struct Message {
        address Sender;
        string Data;
        uint Val;
        uint Time;
    }
    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}
